// Fetch-catalog bridge: a benchmark candidate can be a fetch-catalog id.
// The fetcher fetches it FIRST (consent pre-recorded per the
// experimentPrerequisite pattern — the catalog entries this harness uses are
// marked experiment prerequisites), and the license is surfaced at run start.
//
// Resolution order:
//   1. dist-server/server/fetchCatalog.js (the real catalog; requires
//      `pnpm build:server` — same pattern as scripts/test-fetcher.cjs)
//   2. benchmarks/data/catalog-snapshot.json (a committed fallback snapshot
//      of the benchmark-relevant entries, regenerated by tools/sync-catalog.mjs)
//
// Actual network fetching goes through the real FetchManager from
// dist-server/server/fetcher.js (consent injected for experimentPrerequisite
// entries); offline tests inject a filesystem transport (the test-fetcher
// pattern) and never touch the network.

import fs from 'node:fs'
import { createRequire } from 'node:module'
import path from 'node:path'
import { exists, REPO_ROOT } from './util.mjs'

const require = createRequire(import.meta.url)
const DIST_SERVER = path.join(REPO_ROOT, 'dist-server', 'server')
const SNAPSHOT = path.join(REPO_ROOT, 'benchmarks', 'data', 'catalog-snapshot.json')

function loadDistModule(name) {
  const file = path.join(DIST_SERVER, name)
  if (!exists(file)) return null
  return require(file)
}

let cachedCatalog = undefined

export function catalogAvailable() {
  return loadDistModule('fetchCatalog.js') !== null || exists(SNAPSHOT)
}

export function listCatalog() {
  if (cachedCatalog) return cachedCatalog
  const mod = loadDistModule('fetchCatalog.js')
  if (mod) {
    cachedCatalog = { source: 'dist-server', entries: mod.FETCH_CATALOG }
    return cachedCatalog
  }
  if (exists(SNAPSHOT)) {
    cachedCatalog = { source: 'snapshot', entries: JSON.parse(fs.readFileSync(SNAPSHOT, 'utf8')) }
    return cachedCatalog
  }
  throw new Error('fetch catalog unavailable: build the server first ' +
    '(pnpm build:server) or regenerate the snapshot (node benchmarks/tools/sync-catalog.mjs)')
}

export function findCatalogEntry(id) {
  const { entries } = listCatalog()
  return entries.find((e) => e.id === id) ?? null
}

/** The license banner surfaced at run start (AC: surface the license at run
 *  start). Returns a multiline string; null when the id is not a catalog id. */
export function licenseBanner(id) {
  const entry = findCatalogEntry(id)
  if (!entry) return null
  return [
    `catalog candidate: ${entry.name} (${entry.id})`,
    `  license: ${entry.licenseSpdx}${entry.licenseUrl ? ` — ${entry.licenseUrl}` : ''}`,
    `  terms:   ${entry.licenseNote ?? 'see license url'}`,
    entry.experimentPrerequisite
      ? '  consent: pre-recorded (experiment prerequisite — benchmark use)'
      : '  consent: NOT pre-recorded — acknowledge the license in the fetch UI first',
    `  destination: ${entry.destination?.kind ?? '?'} · ${(entry.files ?? []).length} file(s) · ` +
      `${(((entry.sizeBytes ?? 0) / 1e9)).toFixed(2)} GB`,
  ].join('\n')
}

/** Presence check: does the catalog entry's model file exist in the testbed
 *  models tree (by detectGlob)? The testbed is the benchmark engine root. */
export function entryPresentIn(entry, modelsRoot) {
  if (!entry?.detectGlob || !modelsRoot || !fs.existsSync(modelsRoot)) return false
  const glob = entry.detectGlob
  const pattern = globToRegExp(glob)
  const found = []
  const walk = (dir) => {
    for (const name of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, name.name)
      if (name.isDirectory()) walk(p)
      else if (pattern.test(name.name)) found.push(p)
    }
  }
  try { walk(modelsRoot) } catch { return false }
  return found.length > 0 ? found : false
}

function globToRegExp(glob) {
  const escaped = glob.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')
  return new RegExp(`^${escaped}$`, 'i')
}

/** Fetch a candidate through the REAL fetcher (FetchManager). Consent for
 *  experimentPrerequisite entries is pre-recorded here (the pattern the efc1
 *  and MATLOWAI runs used, now encoded). Requires dist-server built.
 *  options.homeDirectory: scratch fetch home (state + cache).
 *  options.modelsRoot: where model-root destinations resolve (the testbed
 *  models dir or a test fixture tree). options.transport: injectable. */
export async function fetchCandidate(catalogId, {
  homeDirectory, modelsRoot, transport = undefined, log = () => {},
}) {
  const fetcherMod = loadDistModule('fetcher.js')
  const catalogMod = loadDistModule('fetchCatalog.js')
  const entry = findCatalogEntry(catalogId)
  if (!entry) throw new Error(`unknown fetch-catalog id '${catalogId}'`)
  if (!entry.experimentPrerequisite) {
    throw new Error(`catalog entry '${catalogId}' is not an experiment prerequisite — ` +
      'record consent in the app fetch UI first; the benchmark harness only ' +
      'pre-records consent for experimentPrerequisite entries')
  }
  if (!fetcherMod || !catalogMod) {
    throw new Error('dist-server not built — run `pnpm build:server` to enable ' +
      'candidate fetching through the real fetcher')
  }
  const settings = {
    comfyUrl: 'http://127.0.0.1:8188',
    modelRoot: modelsRoot,
    paths: Object.fromEntries(['diffusion_models', 'text_encoders', 'vae', 'loras',
      'model_patches', 'vdn', 'geometry_estimation'].map((k) => [k, path.join(modelsRoot, k)])),
    engine: { checkoutPath: '' },
    fetch: { consents: { [catalogId]: { consented: true, licenseSpdx: entry.licenseSpdx } } },
  }
  const manager = new fetcherMod.FetchManager({
    homeDirectory,
    loadSettings: async () => settings,
    logEvent: (e) => log(JSON.stringify(e).slice(0, 160)),
    logFailure: (stage, error) => log(`fetcher/${stage}: ${String(error).slice(0, 160)}`),
    ...(transport ? { transport } : {}),
  })
  const started = await manager.start(catalogId)
  if (!started.started) throw new Error(`fetch refused: ${started.reason}`)
  // start() is fire-and-forget; poll catalogStatus until placed/failed
  const deadline = Date.now() + 1000 * 60 * 60 * 3
  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, 2000))
    const status = (await manager.catalogStatus()).find((s) => s.id === catalogId)
    if (status?.state === 'placed') return status
    if (status?.state === 'absent' && !status.inFlight) {
      throw new Error(`fetch did not land (state ${status.state}) — see the fetch log`)
    }
  }
  throw new Error('fetch timed out after 3h')
}
